  section_id INTEGER PRIMARY KEY, section_name VARCHAR(40), instructor_id INTEGER
);
CREATE TABLE grades (
  student_id INTEGER REFERENCES students(student_id), section_id INTEGER REFERENCES sections(section_id),
  numeric_grade INTEGER, comments VARCHAR(80), PRIMARY KEY(student_id, section_id)
);
